import datetime


def _weekdays_in_range(start: datetime.date, end: datetime.date) -> int:
    # Count Monday-Friday days d with start <= d < end, in O(1).
    # Anchor at a fixed Monday; days_from_anchor(d) counts days since then.
    anchor = datetime.date(2000, 1, 3)  # a Monday

    def weekday_count_before(d: datetime.date) -> int:
        # Number of weekdays in [anchor, d); may be negative if d < anchor.
        n = (d - anchor).days
        weeks, rem = divmod(n, 7)
        return weeks * 5 + min(rem, 5)

    return weekday_count_before(end) - weekday_count_before(start)


def business_days(start: datetime.date, end: datetime.date,
                  holidays: set[datetime.date]) -> int:
    if end < start:
        return -business_days(end, start, holidays)

    count = _weekdays_in_range(start, end)
    for h in holidays:
        if start <= h < end and h.weekday() < 5:
            count -= 1
    return count
```

Count weekdays in closed-open ranges using the fact that the weekday pattern repeats every 7 days: a full week has 5 business days, so the count for [start, end) can be computed in O(1) from the number of whole weeks plus the leftover days, then the holidays that fall inside the range and on weekdays are subtracted by iterating the set (which is small). For end < start, I compute the count for [end, start) and negate it. Only standard library is used, with no numpy needed since the arithmetic is closed-form.

```python
import datetime


def _weekdays_before(d: datetime.date) -> int:
    # Number of Mon-Fri days in the range [epoch, d), where epoch is a fixed Monday.
    # Using ordinal: date(1,1,1) is a Monday, so ordinal 0 corresponds to a Monday.
    n = d.toordinal() - 1  # days from 0001-01-01 (Monday) to d, exclusive of d
    weeks, rem = divmod(n, 7)
    # rem days into a week starting Monday: count weekdays among the first rem days
    return weeks * 5 + min(rem, 5)


def _count_range(start: datetime.date, end: datetime.date, holidays: set) -> int:
    # Assumes start <= end; counts weekdays d with start <= d < end not in holidays.
    total = _weekdays_before(end) - _weekdays_before(start)
    for h in holidays:
        if start <= h < end and h.weekday() < 5:
            total -= 1
    return total


def business_days(start: datetime.date, end: datetime.date, holidays: set[datetime.date]) -> int:
    if end < start:
        return -_count_range(end, start, holidays)
    return _count_range(start, end, holidays)
