        cost, path = heapq.heappop(heap)
        node = path[-1]
        if node in settled:
            continue
        settled.add(node)
        if node == dst:
            return (cost, path)
        for nxt, w in neighbours(node):
            if nxt in settled:
                continue
            new_cost = cost + w
            new_path = path + [nxt]
            old = best.get(nxt)
            if old is None or (new_cost, new_path) < old:
                best[nxt] = (new_cost, new_path)
                heapq.heappush(heap, (new_cost, new_path))

